            Should -Throw '*No test result files*'
    }

    It 'throws a meaningful error for a nonexistent input path' {
        { & $ScriptPath -Path (Join-Path $TestDrive 'missing-dir') -OutputPath (Join-Path $TestDrive 'y.md') } |
            Should -Throw '*not found*'
    }
}

