            }
    )

    # Distinct failed tests (a test failing in every run appears once).
    $failedDistinct = @(
        $failed |
            Group-Object -Property Suite, Name |
            ForEach-Object {
                [pscustomobject]@{
                    Suite     = $_.Group[0].Suite
                    Name      = $_.Group[0].Name
                    FailCount = $_.Count
                    Runs      = @($_.Group.SourceFile)
                }
            }
    )

    [pscustomobject]@{
        Total       = $Results.Count
        Passed      = $passed.Count
        Failed      = $failed.Count
        Skipped     = $skipped.Count
        Duration    = $duration
        FlakyTests  = $flaky
        FailedTests = $failedDistinct
    }
}

